import 'package:flutter/material.dart';

class SettingsScreen extends StatelessWidget{const SettingsScreen({super.key});@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(12),children:[Text('الإعدادات',style:Theme.of(c).textTheme.headlineSmall?.copyWith(color:const Color(0xFF0D47A1),fontWeight:FontWeight.bold)),const SizedBox(height:10),Card(child:ListTile(leading:const Icon(Icons.business),title:const Text('بيانات الشركة'),subtitle:const Text('الاسم والعنوان والرقم الضريبي'),onTap:()=>_form(c))),Card(child:ListTile(leading:const Icon(Icons.backup),title:const Text('النسخ الاحتياطي'),subtitle:const Text('حفظ نسخة من قاعدة البيانات محلياً'),onTap:()=>_message(c,'تم تجهيز النسخ الاحتياطي'))),Card(child:ListTile(leading:const Icon(Icons.restore),title:const Text('استعادة'),subtitle:const Text('استعادة قاعدة بيانات سابقة'))),Card(child:ListTile(leading:const Icon(Icons.info_outline),title:const Text('حول التطبيق'),subtitle:const Text('ناكستر Naxter — الإصدار 1.0.0')))]);void _form(BuildContext c)=>showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('بيانات الشركة'),content:const Column(mainAxisSize:MainAxisSize.min,children:[TextField(decoration:InputDecoration(labelText:'اسم الشركة')),TextField(decoration:InputDecoration(labelText:'الرقم الضريبي'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c),child:const Text('حفظ'))]);void _message(BuildContext c,String m)=>ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(m)));}
